"""Build V4 results and appendix sections from original prose and saved tables."""
from pathlib import Path
import json
import re
P=Path(__file__).resolve().parents[1]
s=(P/'source/section_05.md').read_text()
def para(prefix):
    return next(x for x in s.splitlines() if x.startswith(prefix))
def table(name):return (P/'tables'/f'{name}.md').read_text().strip()
def original_part(number):
    start=s.index(f'### 5.2.{number} ')
    end=s.find('### ',start+4)
    return s[start:end if end>=0 else len(s)]
def selected(number,prefixes):
    lines=original_part(number).splitlines()
    return '\n'.join(next(x for x in lines if x.startswith(prefix)) for prefix in prefixes)
def image(key):return '{{UPLOAD:'+key+'}}'

